#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NumpyDType {
    Bool,
    Int8,
    Int16,
    Int32,
    Int64,
    Float32,
    Float64,
    Complex64,
    Complex128,
}

impl NumpyDType {
    /// Returns a rank for each dtype so they can be compared.
    fn rank(&self) -> u8 {
        match *self {
            NumpyDType::Bool       => 0,
            NumpyDType::Int8       => 1,
            NumpyDType::Int16      => 2,
            NumpyDType::Int32      => 3,
            NumpyDType::Int64      => 4,
            NumpyDType::Float32    => 5,
            NumpyDType::Float64    => 6,
            NumpyDType::Complex64  => 7,
            NumpyDType::Complex128 => 8,
        }
    }
}

#[derive(Debug, Clone, Copy)]
pub enum NumpyOperand {
    /// A scalar annotated with its dtype
    Scalar(NumpyDType),
    /// An array annotated with its dtype
    Array(NumpyDType),
}

impl NumpyOperand {
    /// Extracts the dtype annotation from the operand
    fn dtype(&self) -> NumpyDType {
        match *self {
            NumpyOperand::Scalar(dt) => dt,
            NumpyOperand::Array(dt)  => dt,
        }
    }
}

/// Given a non-empty list of operands (scalars or arrays), each annotated
/// with a NumpyDType, returns the "promoted" dtype according to the
/// fixed rank order:
///   Bool < Int8 < Int16 < Int32 < Int64 < Float32 < Float64 < Complex64 < Complex128
///
/// The result will be the highest-ranked dtype appearing in the input list.
pub fn result_type(operands: Vec<NumpyOperand>) -> NumpyDType {
    // We know the vector is non-empty, so unwrap() is safe.
    operands
        .iter()
        .map(|op| op.dtype())
        .max_by_key(|dt| dt.rank())
        .unwrap()
}

